#[verus_verify]
impl<T               , G: SpinGuardian> RwLockReadGuard<'_, T, G> {
    #[verifier::exec_allows_no_decreases_clause]
    fn drop(self) {
        proof {
            use_type_invariant(&self);
            use_type_invariant(self.inner);
            lemma_consts_properties();
        }
        proof_decl! {
            let tracked token = self.tracked_token.get();
        }
        atomic_with_ghost!(
            self.inner.lock => fetch_sub(READER);
            update prev -> next;
            ghost g => {
                let prev_usize = prev as usize;
                reveal(RwLock::wf);
                assert(g.read_guard_token is Left);
                assert(g.read_guard_token.left().frac() + token.frac() <= MAX_READER_U64);
                assert(token.frac() == 1);
                assert(g.read_guard_token.left().frac() < MAX_READER_U64);
                assert(no_max_reader_overflow(prev_usize));
                assert(prev_usize & READER_MASK != 0);
                let tracked mut read_guard_token = g.read_guard_token.tracked_take_left();
                read_guard_token.combine(token);
                g.read_guard_token = Sum::tracked_new_left(read_guard_token);
                lemma_consts_properties_prev_next(prev_usize, next as usize);
            }
        );
    }
}


